"""Rank policies: FIFO, strict priority, smallest flow size first and quantized
WFQ finish tags.  All arithmetic is exact integer arithmetic.

Every enqueue attempt is ranked, including attempts that are later rejected by
admission, so FIFO/WFQ rank state advances on rejected attempts too.  Weight
updates affect future attempts only.  Policy state participates in checkpoint
branches: mutable tables are copy-on-write against the scheduler version, so a
checkpoint stores table references and never needs a table-sized copy unless the
table really changes after the checkpoint was taken.
"""

from packet import Pkt

QUANT = 1048576


class SchedulingAlgorithm:
    def __init__(self, *args, **kwargs):
        pass

    def rank_cal(self, pkt: Pkt):
        raise NotImplementedError("Subclasses should implement this method.")

    def post_dequeue(self, pkt: Pkt, rank):
        pass

    def set_weight(self, flow, weight):
        raise NotImplementedError('weight updates apply to the wfq policy')

    def certificate(self):
        raise NotImplementedError("Subclasses should implement this method.")

    def snapshot(self):
        raise NotImplementedError("Subclasses should implement this method.")

    def restore(self, state, ver):
        raise NotImplementedError("Subclasses should implement this method.")


class FifoAlgorithm(SchedulingAlgorithm):
    def __init__(self):
        super().__init__()
        self.time = 0

    def rank_cal(self, pkt: Pkt):
        self.time += 1
        return self.time

    def post_dequeue(self, pkt: Pkt, rank):
        pass

    def set_weight(self, flow, weight):
        pass

    def certificate(self):
        return {'kind': 'fifo', 'time': self.time}

    def snapshot(self):
        return self.time

    def restore(self, state, ver):
        self.time = state


class SpAlgorithm(SchedulingAlgorithm):
    def __init__(self, flowid2pri):
        super().__init__()
        self.flowid2pri = dict(flowid2pri)

    def rank_cal(self, pkt: Pkt):
        return self.flowid2pri.get(pkt.flowid, 0)

    def post_dequeue(self, pkt: Pkt, rank):
        pass

    def set_weight(self, flow, weight):
        pass

    def certificate(self):
        return {'kind': 'sp',
                'levels': [list(item) for item in sorted(self.flowid2pri.items())]}

    def snapshot(self):
        return None

    def restore(self, state, ver):
