class pFabricAlgorithm(SchedulingAlgorithm):
    """Smallest flow size first."""

    def __init__(self):
        super().__init__()

    def rank_cal(self, pkt: Pkt):
        return pkt.flow_size

    def post_dequeue(self, pkt: Pkt, rank):
        pass

    def set_weight(self, flow, weight):
        pass

    def certificate(self):
        return {'kind': 'sff'}

    def snapshot(self):
        return None

    def restore(self, state, ver):
        pass


class WFQAlgorithm(SchedulingAlgorithm):
    def __init__(self, flowid2weight, ver=0):
        super().__init__()
        self.flowid2weight = dict(flowid2weight)
        self.flowid2finish = {flow: 0 for flow in self.flowid2weight}
        self.virtual_time = 0
        self.ver = ver
        self.weight_stamp = ver
        self.finish_stamp = ver

    def _weights(self):
        if self.weight_stamp != self.ver:
            self.flowid2weight = dict(self.flowid2weight)
            self.weight_stamp = self.ver
        return self.flowid2weight

    def _finish(self):
        if self.finish_stamp != self.ver:
            self.flowid2finish = dict(self.flowid2finish)
            self.finish_stamp = self.ver
        return self.flowid2finish

    def rank_cal(self, pkt: Pkt):
        flowid = pkt.flowid
        weights = self._weights()
        finish = self._finish()
        weight = weights.get(flowid)
        if weight is None:
            weight = 1
            weights[flowid] = 1
            finish.setdefault(flowid, 0)
        tag = finish.get(flowid, 0)
        if self.virtual_time > tag:
            tag = self.virtual_time
        length = pkt.length
        tag += (length * QUANT + weight - 1) // weight
        finish[flowid] = tag
        pkt.rank = tag
        return tag

    def post_dequeue(self, pkt: Pkt, rank):
        if rank > self.virtual_time:
            self.virtual_time = rank

    def set_weight(self, flow, weight):
        self._weights()[flow] = weight
        self._finish().setdefault(flow, 0)

    def certificate(self):
        return {'kind': 'wfq',
                'virtual_time': self.virtual_time,
                'weights': [list(item) for item in sorted(self.flowid2weight.items())],
                'finish': [list(item) for item in sorted(self.flowid2finish.items())]}

    def snapshot(self):
        return (self.virtual_time, self.flowid2weight, self.flowid2finish)

    def restore(self, state, ver):
        self.virtual_time, self.flowid2weight, self.flowid2finish = state
        # Keep the stamps: the version has advanced, so the next mutation of
        # either table copies it instead of disturbing the checkpoint.
        self.ver = ver


def make_policy(spec, ver=0):
    kind = spec['kind']
    if kind == 'fifo':
        return FifoAlgorithm()
    if kind == 'sp':
        return SpAlgorithm(spec['levels'])
    if kind == 'sff':
        return pFabricAlgorithm()
    if kind == 'wfq':
        return WFQAlgorithm(spec['weights'], ver)
    raise ValueError('unknown policy kind: %r' % (kind,))
